SELECT th.id AS historyId, t.id AS taskId, t.title, t.type, t.priority, th.status, th.status_time, th.feedback FROM task_history th LEFT JOIN task t ON th.task_id = t.id
AND t.title LIKE CONCAT('%', #{search}, '%')
AND t.type = #{type}
AND th.status = #{status}
AND th.status_time >= #{startDate}
AND th.status_time <= #{endDate}
ORDER BY th.status_time DESC LIMIT #{page}, #{size}

SELECT COUNT(*) count
FROM
task_history th
LEFT JOIN
task t ON th.task_id = t.id


        AND t.title LIKE CONCAT('%', #{search}, '%')


        AND t.type = #{type}


        AND th.status = #{status}


        AND th.status_time >= #{startDate}


        AND th.status_time <= #{endDate}


ORDER BY th.status_time, task_id DESC

SELECT th.id as historyId, t.id as taskId, t.title, t.type, t.priority, th.status, th.status_time, th.feedback FROM task_history th LEFT JOIN task t ON th.task_id = t.id WHERE t.assigned_to_id = #{userId}
AND (t.title LIKE CONCAT('%', #{search}, '%') OR t.description LIKE CONCAT('%', #{search}, '%'))
AND th.status = #{status}
AND t.type = #{type}
AND DATE(th.status_time) >= DATE(#{startDate})
AND DATE(th.status_time) <= DATE(#{endDate})
ORDER BY th.status_time DESC LIMIT #{page}, #{size}

SELECT COUNT(*) FROM task_history th LEFT JOIN task t ON th.task_id = t.id WHERE t.assigned_to_id = #{userId}
AND (t.title LIKE CONCAT('%', #{search}, '%') OR t.description LIKE CONCAT('%', #{search}, '%'))
AND th.status = #{status}
AND t.type = #{type}
AND DATE(th.status_time) >= DATE(#{startDate})
AND DATE(th.status_time) <= DATE(#{endDate})
